CREATE OR REPLACE FUNCTION authorization_private.copy_public_shared_core_apply(p_business uuid, p_environment text, p_key uuid, p_actor uuid, p_reason text, p_changes jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare envelope jsonb; prior public.shared_core_commands; c jsonb; v bigint;
 result jsonb:='[]'; ordinal integer:=0;
begin if authorization_private.member_role(p_business,p_environment) is null then raise exception 'Business context denied' using errcode='42501';end if;
 if p_business is null or p_environment is null or p_environment<>'preview' or p_key is null or p_actor is null
 or p_reason is null or length(btrim(p_reason)) not between 4 and 1000
 or p_changes is null or octet_length(p_changes::text)>1048576 or jsonb_typeof(p_changes)<>'array' or jsonb_array_length(p_changes) not between 1 and 100
 then raise exception 'Invalid command envelope' using errcode='22023';end if;
 if p_actor is distinct from auth.uid() or coalesce((auth.jwt()->>'is_anonymous')::boolean,true)
 or not exists(select 1 from public.businesses where id=p_business and owner_id=p_actor)
 then raise exception 'Actor denied' using errcode='42501';end if;
 -- Validate exact shape and canonical order before any writes or locks.
 for c in select value from jsonb_array_elements(p_changes) loop
  if jsonb_typeof(c)<>'object' or (select count(*) from jsonb_object_keys(c))<>5
  or not (c ?& array['kind','id','expected_version','schema','snapshot'])
  or jsonb_typeof(c->'kind')<>'string' or (c->>'kind') !~ '^[a-z][a-z0-9_.]{0,63}$'
  or jsonb_typeof(c->'id')<>'string' or (c->>'id') !~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
  or jsonb_typeof(c->'expected_version')<>'number' or (c->>'expected_version') !~ '^(0|[1-9][0-9]{0,17})$'
  or c->'schema'<>'1'::jsonb or jsonb_typeof(c->'snapshot')<>'object'
  then raise exception 'Invalid change contract' using errcode='22023';end if;
 end loop;
 if (select count(*) from (select distinct value->>'kind',value->>'id' from jsonb_array_elements(p_changes)) x)<>jsonb_array_length(p_changes)
 then raise exception 'Duplicate aggregate' using errcode='22023';end if;
 select jsonb_build_object('schema',1,'actor',p_actor,'reason',p_reason,'changes',jsonb_agg(value order by value->>'kind' collate "C",value->>'id' collate "C"))
 into envelope from jsonb_array_elements(p_changes);
 -- One tenant/environment transaction lock FIRST. Hash collisions only serialize.
 -- Multi-business transactions and legacy adapters are not supported.
 perform pg_advisory_xact_lock(hashtextextended(p_business::text||':'||p_environment,73003));
 select * into prior from public.shared_core_commands where business_id=p_business and environment=p_environment and idempotency_key=p_key;
 if found then
  if prior.envelope<>envelope then raise exception 'Idempotency payload conflict' using errcode='22023';end if;
  return prior.result; -- Exact retry wins over expected-version staleness.
 end if;
 for c in select value from jsonb_array_elements(envelope->'changes') loop
  select version into v from public.shared_core_aggregates where business_id=p_business and environment=p_environment and kind=c->>'kind' and id=(c->>'id')::uuid for update;
  v:=coalesce(v,0);
  if v<>(c->>'expected_version')::bigint then raise exception 'Stale aggregate version' using errcode='40001';end if;
  insert into public.shared_core_aggregates values(p_business,p_environment,c->>'kind',(c->>'id')::uuid,v+1,c->'snapshot')
  on conflict(business_id,environment,kind,id) do update set version=excluded.version,snapshot=excluded.snapshot;
  result:=result||jsonb_build_array(jsonb_build_object('kind',c->>'kind','id',c->>'id','version',v+1));
 end loop;
 insert into public.shared_core_commands values(p_business,p_environment,p_key,p_actor,p_reason,envelope,result,transaction_timestamp());
 for c in select value from jsonb_array_elements(envelope->'changes') loop
  ordinal:=ordinal+1;
  insert into public.shared_core_events values(p_business,p_environment,p_key,ordinal,c->>'kind',(c->>'id')::uuid,(c->>'expected_version')::bigint,(c->>'expected_version')::bigint+1,c->'snapshot',1);
 end loop;
 return result;
end $function$

CREATE OR REPLACE FUNCTION authorization_private.copy_quote_private_owner_write(p_business uuid, p_environment text, p_id uuid, p_version integer, p_action text, p_document jsonb, p_expiry date, p_enquiry uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare q public.business_quotes;b public.businesses;c text;z text;s jsonb;scope jsonb;
begin if authorization_private.member_role(p_business,p_environment) is null then raise exception 'Business context denied' using errcode='42501';end if;
 select * into b from public.businesses where id=p_business and authorization_private.member_role(p_business,p_environment) is not null and not coalesce((auth.jwt()->>'is_anonymous')::boolean,true);
 if not found or not exists(select 1 from quote_private.ingress where environment=p_environment and enabled) then raise exception 'Quotes unavailable';end if;
 if p_action not in ('save','send') or p_action is null or p_id is null or p_version is null then raise exception 'Check quote details';end if;
 select * into q from public.business_quotes where id=p_id for update;
 if found then
 if q.business_id<>p_business or q.environment<>p_environment or q.version<>p_version or q.status<>'Draft' then raise exception 'Quote changed or unavailable. Reload before saving.';end if;
 else
 if p_version<>0 or p_action<>'save' then raise exception 'Quote changed or unavailable. Reload before saving.';end if;
 end if;
 if p_action='save' then
 if q.id is not null then scope=q.document->'scope';elsif p_enquiry is not null then select r.scope into scope from public.business_booking_requests r where r.id=p_enquiry and r.business_id=p_business and r.environment=p_environment;end if;
 if scope is not null then p_document=(p_document-'scope')||jsonb_build_object('scope',scope);elsif p_document ? 'scope' then raise exception 'Scope must originate from a booking request.';end if;
 if not quote_private.valid(p_document) or p_expiry is null or p_expiry < (now() at time zone b.time_zone)::date or p_expiry > (now() at time zone b.time_zone)::date+366 then raise exception 'Check quote details and expiry';end if;
 select draft->>'currency' into c from public.business_service_catalogues where business_id=p_business and environment=p_environment;
 if p_document->>'currency'<>coalesce(c,'ZAR') then raise exception 'Business currency changed. Reload before saving.';end if;
 if p_enquiry is not null and not exists(select 1 from public.business_enquiries where id=p_enquiry and business_id=p_business and environment=p_environment) then raise exception 'Enquiry unavailable';end if;
 if q.id is null then insert into public.business_quotes(id,business_id,environment,enquiry_id,document,expires_on) values(p_id,p_business,p_environment,p_enquiry,p_document,p_expiry);
 else update public.business_quotes set document=p_document,expires_on=p_expiry,version=version+1 where id=p_id;end if;
 else
 if q.expires_on < (now() at time zone b.time_zone)::date then raise exception 'Update the expiry before sending.';end if;
 -- Capture explicit public business details only; no account metadata.
 select draft into s from public.business_profiles where business_id=p_business and environment=p_environment;
 s=jsonb_build_object('name',coalesce(nullif(s->>'name',''),b.name),'email',coalesce(s->>'email',''),'phone',coalesce(s->>'phone',''),'time_zone',b.time_zone);
 update public.business_quotes set status='Sent',sender=s,share_token=encode(extensions.gen_random_bytes(32),'hex'),sent_at=now(),version=version+1 where id=p_id;
 end if;
 return jsonb_build_object('id',p_id);
end$function$

CREATE OR REPLACE FUNCTION authorization_private.copy_quote_private_send(p_business uuid, p_environment text, p_id uuid, p_version integer, p_free_confirmed boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare q public.business_quotes;
