   foreach k in array array['slug','name','title','introduction','coverage','seo_title','seo_description','action'] loop
    if jsonb_typeof(a->k) is distinct from 'string' or a->>k ~ '[\u0001-\u0008\u000b\u000c\u000e-\u001f\u007f]' then return false;end if;
   end loop;
   if a->>'slug'<>area_key or char_length(btrim(a->>'name')) not between 1 and 120 or a->>'name'=any(names) or char_length(a->>'title')>120 or char_length(a->>'introduction')>600 or char_length(a->>'coverage')>3000 or char_length(a->>'seo_title')>120 or char_length(a->>'seo_description')>300 or char_length(a->>'action')>80 or jsonb_typeof(a->'published') is distinct from 'boolean' or jsonb_typeof(a->'services') is distinct from 'array' or jsonb_array_length(a->'services')>50 then return false;end if;
   names=array_append(names,a->>'name');
   if a->'published'='true'::jsonb and (btrim(a->>'title')='' or btrim(a->>'introduction')='' or btrim(a->>'coverage')='' or btrim(a->>'action')='') then return false;end if;
   for service in select value from jsonb_array_elements(a->'services') loop
    if jsonb_typeof(service) is distinct from 'string' or service#>>'{}' !~ '^[a-f0-9]{32}$' then return false;end if;
   end loop;
   if (select count(distinct value) from jsonb_array_elements(a->'services'))<>jsonb_array_length(a->'services') then return false;end if;
  end loop;
  d=d-'area_pages';
 end if;
 if d ? 'presentation' then
  seo=d->'presentation';
  if jsonb_typeof(seo) is distinct from 'object' or not seo ?& array['accent','font','whatsapp','street','city','region','postal','country'] or (seo-array['accent','font','whatsapp','street','city','region','postal','country','logo_size','show_name'])<>'{}'::jsonb then return false;end if;
  foreach k in array array['accent','font','whatsapp','street','city','region','postal','country'] loop
   if jsonb_typeof(seo->k) is distinct from 'string' or seo->>k ~ '[\u0001-\u0008\u000b\u000c\u000e-\u001f\u007f]' then return false;end if;
  end loop;
  if seo->>'accent' not in ('','forest','navy','plum') or seo->>'font' not in ('','serif','sans') or (seo->>'whatsapp'<>'' and seo->>'whatsapp' !~ '^[1-9][0-9]{6,14}$') or (seo->>'country'<>'' and seo->>'country' !~ '^[A-Z]{2}$') or char_length(seo->>'street')>200 or char_length(seo->>'city')>100 or char_length(seo->>'region')>100 or char_length(seo->>'postal')>20 then return false;end if;
  if seo ? 'logo_size' and (jsonb_typeof(seo->'logo_size') is distinct from 'string' or seo->>'logo_size' not in ('32','48','64','80')) then return false;end if;
  if seo ? 'show_name' and (jsonb_typeof(seo->'show_name') is distinct from 'string' or seo->>'show_name' not in ('yes','no')) then return false;end if;
  d=d-'presentation';
 end if;
 if d ? 'seo' then
  seo=d->'seo';
  if jsonb_typeof(seo) is distinct from 'object' or not seo ?& array['pages','image','image_alt'] or (seo-array['pages','image','image_alt'])<>'{}'::jsonb then return false;end if;
  if jsonb_typeof(seo->'image_alt') is distinct from 'string' or char_length(seo->>'image_alt')>200 or seo->>'image_alt' ~ '[\u0001-\u0008\u000b\u000c\u000e-\u001f\u007f]' then return false;end if;
  if jsonb_typeof(seo->'pages') is distinct from 'object' or ((seo->'pages')-array['home','services','how-it-works','areas','contact'])<>'{}'::jsonb then return false;end if;
  for page_key,page_doc in select key,value from jsonb_each(seo->'pages') loop
   if jsonb_typeof(page_doc) is distinct from 'object' or not page_doc ?& array['title','description','image'] or (page_doc-array['title','description','image'])<>'{}'::jsonb then return false;end if;
   foreach k in array array['title','description','image'] loop
    if jsonb_typeof(page_doc->k) is distinct from 'string' or page_doc->>k ~ '[\u0001-\u0008\u000b\u000c\u000e-\u001f\u007f]' then return false;end if;
   end loop;
   if char_length(page_doc->>'title')>120 or char_length(page_doc->>'description')>300 or page_doc->>'image' not in ('auto','hero','logo','none') then return false;end if;
  end loop;
  l=seo->'image';
  if l<>'null'::jsonb then
   if jsonb_typeof(l) is distinct from 'object' or (select count(*) from jsonb_object_keys(l))<>2 or not l ?& array['mime','data'] or jsonb_typeof(l->'mime') is distinct from 'string' or jsonb_typeof(l->'data') is distinct from 'string' or l->>'mime' not in ('image/png','image/jpeg','image/webp') or char_length(l->>'data')>200000 or l->>'data' !~ '^[A-Za-z0-9+/]+={0,2}$' or btrim(seo->>'image_alt')='' then return false;end if;
  end if;
  d=d-'seo';
 end if;
 if d ? 'pages' then
  if jsonb_typeof(d->'pages') is distinct from 'object' or ((d->'pages') - array['services','how-it-works','areas','contact'])<>'{}'::jsonb then return false;end if;
  for page_key,page_doc in select key,value from jsonb_each(d->'pages') loop
   if jsonb_typeof(page_doc) is distinct from 'object' or not page_doc ?& array['title','introduction','body'] or (page_doc - array['title','introduction','body','steps'])<>'{}'::jsonb then return false;end if;
   foreach k in array array['title','introduction','body'] loop
    if jsonb_typeof(page_doc->k) is distinct from 'string' or page_doc->>k ~ '[\u0001-\u0008\u000b\u000c\u000e-\u001f\u007f]' then return false;end if;
   end loop;
   if char_length(page_doc->>'title')>120 or char_length(page_doc->>'introduction')>600 or char_length(page_doc->>'body')>3000 then return false;end if;
   if page_doc ? 'steps' then
    if page_key<>'how-it-works' or jsonb_typeof(page_doc->'steps') is distinct from 'array' or jsonb_array_length(page_doc->'steps')<>3 then return false;end if;
    for step in select value from jsonb_array_elements(page_doc->'steps') loop
     if jsonb_typeof(step) is distinct from 'array' or jsonb_array_length(step)<>2 or jsonb_typeof(step->0) is distinct from 'string' or jsonb_typeof(step->1) is distinct from 'string' or char_length(step->>0)>120 or char_length(step->>1)>600 or step->>0 ~ '[\u0001-\u0008\u000b\u000c\u000e-\u001f\u007f]' or step->>1 ~ '[\u0001-\u0008\u000b\u000c\u000e-\u001f\u007f]' then return false;end if;
    end loop;
   end if;
  end loop;
  d=d-'pages';
 end if;
 if d ? 'homepage' then
  hp=d->'homepage';
  if hp ? 'benefit_section' then
   section=hp->'benefit_section';
   if jsonb_typeof(section) is distinct from 'object' or (select count(*) from jsonb_object_keys(section))<>3 or not section ?& array['title','visible','cards'] or jsonb_typeof(section->'title') is distinct from 'string' or char_length(section->>'title')>120 or section->>'title' ~ '[[:cntrl:]]' or jsonb_typeof(section->'visible') is distinct from 'boolean' or jsonb_typeof(section->'cards') is distinct from 'array' or jsonb_array_length(section->'cards')>6 then return false;end if;
   for card in select value from jsonb_array_elements(section->'cards') loop
    if jsonb_typeof(card) is distinct from 'object' or (select count(*) from jsonb_object_keys(card))<>3 or not card ?& array['icon','title','description'] or jsonb_typeof(card->'icon') is distinct from 'string' or card->>'icon' not in ('home','calendar','message','check','heart','star') or jsonb_typeof(card->'title') is distinct from 'string' or char_length(btrim(card->>'title')) not between 1 and 200 or card->>'title' ~ '[[:cntrl:]]' or jsonb_typeof(card->'description') is distinct from 'string' or char_length(card->>'description')>200 or card->>'description' ~ '[[:cntrl:]]' then return false;end if;
   end loop;
   hp=hp-'benefit_section';
  end if;
  if jsonb_typeof(hp) is distinct from 'object' or (select count(*) from jsonb_object_keys(hp))<>5 or not hp ?& array['headline','introduction','image_alt','benefits','image'] then return false;end if;
  foreach k in array array['headline','introduction','image_alt'] loop
   if jsonb_typeof(hp->k) is distinct from 'string' or hp->>k ~ '[\u0001-\u0008\u000b\u000c\u000e-\u001f\u007f]' then return false;end if;
  end loop;
  if char_length(hp->>'headline')>160 or char_length(hp->>'introduction')>600 or char_length(hp->>'image_alt')>200 then return false;end if;
  if jsonb_typeof(hp->'benefits') is distinct from 'array' or jsonb_array_length(hp->'benefits')>6 then return false;end if;
  for benefit in select value from jsonb_array_elements(hp->'benefits') loop
   if jsonb_typeof(benefit) is distinct from 'string' or char_length(benefit#>>'{}') not between 1 and 200 or benefit#>>'{}' ~ '[\u0001-\u001f\u007f]' then return false;end if;
  end loop;
  l=hp->'image';
  if l<>'null'::jsonb then
   if jsonb_typeof(l) is distinct from 'object' or (select count(*) from jsonb_object_keys(l))<>2 or not l ?& array['mime','data'] or jsonb_typeof(l->'mime') is distinct from 'string' or jsonb_typeof(l->'data') is distinct from 'string' or l->>'mime' not in ('image/png','image/jpeg','image/webp') or char_length(l->>'data')>200000 or l->>'data' !~ '^[A-Za-z0-9+/]+={0,2}$' or btrim(hp->>'image_alt')='' then return false;end if;
  end if;
  d=d-'homepage';
 end if;
 if jsonb_typeof(d) is distinct from 'object' or (select count(*) from jsonb_object_keys(d))<>8 or not d ?& array['name','description','email','phone','website','areas','hours','logo'] then return false; end if;
 foreach k in array array['name','description','email','phone','website','areas'] loop
  if jsonb_typeof(d->k) is distinct from 'string' or d->>k ~ '[\u0001-\u0008\u000b\u000c\u000e-\u001f\u007f]' then return false; end if;
 end loop;
 if char_length(d->>'name') not between 2 and 120 or char_length(d->>'description')>2000 or char_length(d->>'email')>254 or char_length(d->>'phone')>40 or char_length(d->>'website')>500 or char_length(d->>'areas')>1000 then return false;end if;
 if (d->>'email'<>'' and d->>'email' !~ '^[^[:space:]@]+@[^[:space:]@]+\.[^[:space:]@]+$') or (d->>'phone'<>'' and d->>'phone' !~ '^[+0-9 ()-]{5,40}$') or (d->>'website'<>'' and d->>'website' !~ '^https://[^/@[:space:]]+([/:?#][^[:space:]]*)?$') then return false; end if;
 if jsonb_typeof(d->'hours') is distinct from 'array' or jsonb_array_length(d->'hours')<>7 then return false;end if;
 for h in select value from jsonb_array_elements(d->'hours') loop
  if h='null'::jsonb then continue;end if;
  if jsonb_typeof(h) is distinct from 'array' or jsonb_array_length(h)<>2 then return false;end if;
  if jsonb_typeof(h->0) is distinct from 'string' or jsonb_typeof(h->1) is distinct from 'string' or h->>0 !~ '^([01][0-9]|2[0-3]):[0-5][0-9]$' or h->>1 !~ '^([01][0-9]|2[0-3]):[0-5][0-9]$' or h->>0>=h->>1 then return false;end if;
 end loop;
 l=d->'logo';if l<>'null'::jsonb then
  if jsonb_typeof(l) is distinct from 'object' or (select count(*) from jsonb_object_keys(l))<>2 or not l ?& array['mime','data'] or jsonb_typeof(l->'mime') is distinct from 'string' or jsonb_typeof(l->'data') is distinct from 'string' or l->>'mime' not in ('image/png','image/jpeg','image/webp') or char_length(l->>'data')>200000 or l->>'data' !~ '^[A-Za-z0-9+/]+={0,2}$' then return false;end if;
 end if;
 return true;
exception when others then return false;
end $function$

CREATE OR REPLACE FUNCTION public.business_services_publish(p_business uuid, p_environment text, p_version integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare r public.business_service_catalogues; snap jsonb;
begin
 -- Match profile publishing lock order to serialize snapshot changes and avoid lost updates.
 perform 1 from public.business_profiles where business_id=p_business and environment=p_environment for update;
 select * into r from public.business_service_catalogues where business_id=p_business and environment=p_environment for update;
 if not found or r.version<>p_version then raise exception 'Services changed. Reload before saving or publishing.';end if;
 select jsonb_build_object('currency',r.draft->>'currency','items',coalesce(jsonb_agg(value) filter(where (value->>'visible')::boolean and not (value->>'archived')::boolean),'[]'::jsonb)) into snap from jsonb_array_elements(r.draft->'items');
 update public.business_service_catalogues set published=snap,published_version=version where business_id=p_business and environment=p_environment;
 update public.business_public_pages set services=snap where business_id=p_business and environment=p_environment;
 return '{}'::jsonb;
end $function$

CREATE OR REPLACE FUNCTION public.business_services_save_image(p_business uuid, p_environment text, p_draft jsonb, p_version integer, p_service text, p_image jsonb, p_alt text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare media uuid; next_draft jsonb;
begin
 if not exists(select 1 from public.businesses where id=p_business) then raise exception 'Services permission denied';end if;
 if not public.business_services_valid(p_draft) or p_alt is null or char_length(btrim(p_alt)) not between 1 and 200 or p_alt ~ '[[:cntrl:]]' or not exists(select 1 from jsonb_array_elements(p_draft->'items') s where s->>'id'=p_service and s->>'archived'='false') then raise exception 'Check service image details.';end if;
 insert into public.business_service_images(business_id,environment,image) values(p_business,p_environment,p_image) returning id into media;
 select jsonb_set(p_draft,'{items}',jsonb_agg(case when s->>'id'=p_service then s||jsonb_build_object('photo',jsonb_build_object('id',replace(media::text,'-',''),'alt',btrim(p_alt))) else s end order by ord)) into next_draft from jsonb_array_elements(p_draft->'items') with ordinality as entries(s,ord);
 return public.business_services_save(p_business,p_environment,next_draft,p_version);
end$function$

CREATE OR REPLACE FUNCTION public.business_services_save(p_business uuid, p_environment text, p_draft jsonb, p_version integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare n integer;
begin
 if not exists(select 1 from public.businesses where id=p_business) then raise exception 'Services permission denied';end if;
 if p_version=0 then insert into public.business_service_catalogues(business_id,environment,draft) values(p_business,p_environment,p_draft);
 else update public.business_service_catalogues set draft=p_draft,version=version+1 where business_id=p_business and environment=p_environment and version=p_version;get diagnostics n=row_count;if n<>1 then raise exception 'Services changed. Reload before saving or publishing.';end if;end if;
 return '{}'::jsonb;
end $function$

CREATE OR REPLACE FUNCTION public.business_services_valid(d jsonb)
 RETURNS boolean
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO ''
AS $function$
declare s jsonb; k text; photo jsonb; ids text[]='{}';
begin
 if jsonb_typeof(d) is distinct from 'object' or (select count(*) from jsonb_object_keys(d))<>2 or not d ?& array['currency','items'] or jsonb_typeof(d->'currency') is distinct from 'string' or d->>'currency' not in ('ZAR','USD','GBP','EUR','AUD','CAD','NZD','BWP','NAD','ZMW','KES','NGN','GHS','MUR','SZL','LSL','MZN','UGX','TZS','RWF','JPY','INR','AED','CHF') or jsonb_typeof(d->'items') is distinct from 'array' or jsonb_array_length(d->'items')>100 then return false;end if;
 for s in select value from jsonb_array_elements(d->'items') loop
  if jsonb_typeof(s) is distinct from 'object' or (s-array['id','name','description','duration','mode','amount','visible','archived','options','photo'])<>'{}'::jsonb or not s ?& array['id','name','description','duration','mode','amount','visible','archived'] then return false;end if;
  foreach k in array array['id','name','description','mode'] loop
   if jsonb_typeof(s->k) is distinct from 'string' or s->>k ~ '[\u0001-\u0008\u000b\u000c\u000e-\u001f\u007f]' then return false;end if;
  end loop;
  if s->>'id' !~ '^[a-f0-9]{32}$' or s->>'id'=any(ids) or char_length(btrim(s->>'name')) not between 2 and 120 or char_length(s->>'description')>2000 or s->>'mode' not in ('fixed','from','quote') or jsonb_typeof(s->'duration') is distinct from 'number' or s->>'duration' !~ '^[0-9]+$' or (s->>'duration')::integer not between 1 and 10080 or jsonb_typeof(s->'visible') is distinct from 'boolean' or jsonb_typeof(s->'archived') is distinct from 'boolean' then return false;end if;
  if s ? 'options' and not request_private.options_valid(s->'options') then return false;end if;
  if s ? 'photo' then
   photo=s->'photo';
   if jsonb_typeof(photo) is distinct from 'object' or (select count(*) from jsonb_object_keys(photo))<>2 or not photo ?& array['id','alt'] or jsonb_typeof(photo->'id') is distinct from 'string' or photo->>'id' !~ '^[a-f0-9]{32}$' or jsonb_typeof(photo->'alt') is distinct from 'string' or char_length(btrim(photo->>'alt')) not between 1 and 200 or photo->>'alt' ~ '[[:cntrl:]]' then return false;end if;
  end if;
  if d->>'currency' in ('JPY','UGX','RWF') and exists(select 1 from jsonb_array_elements(coalesce(s->'options','[]')) o where (o->>'price')::bigint%100<>0) then return false;end if;
  ids=array_append(ids,s->>'id');
  if s->>'mode'='quote' then if s->'amount'<>'null'::jsonb then return false;end if;
  elsif jsonb_typeof(s->'amount') is distinct from 'number' or s->>'amount' !~ '^[0-9]+$' or (s->>'amount')::bigint not between 0 and 999999999 then return false;end if;
  if d->>'currency' in ('JPY','UGX','RWF') and s->>'mode'<>'quote' and (s->>'amount')::bigint%100<>0 then return false;end if;
 end loop;return true;
exception when others then return false;
end $function$

CREATE OR REPLACE FUNCTION public.business_staff_invite_accept(p_id uuid, p_environment text, p_token text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare i authorization_private.staff_invites; s public.business_staff; b uuid; e text; sid uuid; verified text;
begin
 select business_id,environment,staff_id into b,e,sid from authorization_private.staff_invites where id=p_id;
 perform 1 from public.businesses where id=b for update;
 select * into s from public.business_staff where id=sid and business_id=b and environment=e for update;
 select * into i from authorization_private.staff_invites where id=p_id for update;
 select lower(email) into verified from auth.users where id=auth.uid() and email_confirmed_at is not null for share;
 if p_environment is null or i.environment is distinct from p_environment or i.id is null or verified is null or verified<>i.email or coalesce((auth.jwt()->>'is_anonymous')::boolean,true) or p_token is null or p_token!~'^[a-f0-9]{64}$' or i.token_hash<>extensions.digest(p_token,'sha256') or i.accepted_at is not null or i.revoked_at is not null or i.expires_at<=clock_timestamp() or not authorization_private.staff_onboarding_scope(b,e) then raise exception 'Invitation unavailable or wrong account';end if;
 if not s.active or lower(btrim(s.email))<>i.email then raise exception 'Staff details changed; request a new invitation';end if;
 insert into public.business_memberships values(b,e,auth.uid(),i.role,true) on conflict(business_id,environment,user_id) do update set active=true,role=excluded.role where not public.business_memberships.active and public.business_memberships.role<>'owner';
 if not found then raise exception 'Membership already active';end if;
 if i.role='worker' then
  if exists(select 1 from authorization_private.worker_identities where business_id=b and environment=e and (user_id=auth.uid() or staff_id=i.staff_id) and (user_id<>auth.uid() or staff_id<>i.staff_id)) then raise exception 'Worker link conflict';end if;
  insert into authorization_private.worker_identities values(b,e,auth.uid(),i.staff_id) on conflict(business_id,environment,user_id) do nothing;
 end if;
 update authorization_private.staff_invites set accepted_at=clock_timestamp(),user_id=auth.uid() where id=i.id;
 insert into authorization_private.events(business_id,environment,actor,action,subject) values(b,e,auth.uid(),'staff.invite.accepted',i.id);
 return jsonb_build_object('business_id',b,'environment',e,'role',i.role);
end$function$

CREATE OR REPLACE FUNCTION public.business_staff_invite_preview(p_id uuid, p_environment text, p_token text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare i authorization_private.staff_invites; verified text;
begin
 select lower(email) into verified from auth.users where id=auth.uid() and email_confirmed_at is not null;
 select * into i from authorization_private.staff_invites where id=p_id;
 if p_environment is null or i.environment is distinct from p_environment or verified is null or coalesce((auth.jwt()->>'is_anonymous')::boolean,true) or i.id is null or verified<>i.email or p_token is null or p_token!~'^[a-f0-9]{64}$' or i.token_hash<>extensions.digest(p_token,'sha256') or i.accepted_at is not null or i.revoked_at is not null or i.expires_at<=clock_timestamp() or not authorization_private.staff_onboarding_scope(i.business_id,i.environment) then raise exception 'Invitation unavailable';end if;
 return jsonb_build_object('business',(select name from public.businesses where id=i.business_id),'environment',i.environment,'role',i.role,'email',i.email);
end$function$

CREATE OR REPLACE FUNCTION public.business_staff_invite_revoke(p_business uuid, p_environment text, p_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$begin
 perform authorization_private.require_owner(p_business,p_environment);if not authorization_private.staff_onboarding_scope(p_business,p_environment) then raise exception 'Staff onboarding unavailable';end if;perform 1 from public.businesses where id=p_business for update;
 update authorization_private.staff_invites set revoked_at=clock_timestamp(),delivery=case when delivery='provider_accepted' then delivery else 'cancelled' end where id=p_id and business_id=p_business and environment=p_environment and revoked_at is null and accepted_at is null;
 if not found then raise exception 'Invitation unavailable';end if;
 insert into authorization_private.events(business_id,environment,actor,action,subject) values(p_business,p_environment,auth.uid(),'staff.invite.revoked',p_id);
end$function$

CREATE OR REPLACE FUNCTION public.business_staff_invite(p_business uuid, p_environment text, p_staff uuid, p_role text, p_hash text, p_sealed text, p_replace uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare s public.business_staff; i uuid;
begin
 perform authorization_private.require_owner(p_business,p_environment);
 if not authorization_private.staff_onboarding_scope(p_business,p_environment) then raise exception 'Invitation unavailable';end if;
 perform 1 from public.businesses where id=p_business for update;
 select * into s from public.business_staff where id=p_staff and business_id=p_business and environment=p_environment for update;
 if not found or not s.active or s.email='' or p_role not in ('manager','receptionist','worker') or p_role is null or p_hash is null or p_hash!~'^[a-f0-9]{64}$' or p_sealed is null or length(p_sealed) not between 100 and 4096 then raise exception 'Check invitation details';end if;
 if exists(select 1 from authorization_private.worker_identities w join public.business_memberships m using(business_id,environment,user_id) where w.business_id=p_business and w.environment=p_environment and w.staff_id=p_staff and m.active) then raise exception 'Staff already linked';end if;
 if exists(select 1 from authorization_private.staff_invites where business_id=p_business and environment=p_environment and staff_id=p_staff and accepted_at is not null and user_id in (select user_id from public.business_memberships where business_id=p_business and environment=p_environment and active)) then raise exception 'Staff already has access';end if;
 if (select count(*) from authorization_private.staff_invites where business_id=p_business and environment=p_environment and created_at>clock_timestamp()-interval '1 hour')>=20 then raise exception 'Invitation rate limit';end if;
 if p_replace is not null then
  update authorization_private.staff_invites set revoked_at=clock_timestamp(),delivery=case when delivery='provider_accepted' then delivery else 'cancelled' end where id=p_replace and business_id=p_business and environment=p_environment and staff_id=p_staff and accepted_at is null and revoked_at is null and created_at<clock_timestamp()-interval '60 seconds';
  if not found then raise exception 'Invitation changed or resend too soon';end if;
 end if;
 if exists(select 1 from authorization_private.staff_invites where business_id=p_business and environment=p_environment and (staff_id=p_staff or email=lower(btrim(s.email))) and accepted_at is null and revoked_at is null and expires_at>clock_timestamp()) then raise exception 'Invitation already pending';end if;
 if exists(select 1 from authorization_private.invitations i join auth.users u on u.id=i.recipient where i.business_id=p_business and i.environment=p_environment and lower(u.email)=lower(btrim(s.email)) and i.accepted_at is null and i.revoked_at is null and i.expires_at>clock_timestamp()) then raise exception 'Manual invitation pending; revoke it first';end if;
 insert into authorization_private.staff_invites(business_id,environment,staff_id,email,role,token_hash,sealed_token,created_by) values(p_business,p_environment,p_staff,lower(btrim(s.email)),p_role,decode(p_hash,'hex'),p_sealed,auth.uid()) returning id into i;
 insert into authorization_private.events(business_id,environment,actor,action,subject) values(p_business,p_environment,auth.uid(),'staff.invite.created',i);
 return jsonb_build_object('id',i);
end$function$

CREATE OR REPLACE FUNCTION public.business_staff_mail_claim(p_environment text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare i authorization_private.staff_invites;
begin
 update authorization_private.staff_invites set delivery='failed',lease_until=null where environment=p_environment and delivery='sending' and attempts>=6 and lease_until<clock_timestamp();
