CREATE OR REPLACE FUNCTION public.shared_core_apply(p_business uuid, p_environment text, p_key uuid, p_actor uuid, p_reason text, p_changes jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare envelope jsonb; prior public.shared_core_commands; c jsonb; v bigint;
 result jsonb:='[]'; ordinal integer:=0;
begin
 if p_business is null or p_environment is null or p_environment<>'preview' or p_key is null or p_actor is null
 or p_reason is null or length(btrim(p_reason)) not between 4 and 1000
 or p_changes is null or octet_length(p_changes::text)>1048576 or jsonb_typeof(p_changes)<>'array' or jsonb_array_length(p_changes) not between 1 and 100
 then raise exception 'Invalid command envelope' using errcode='22023';end if;
 if p_actor is distinct from auth.uid() or coalesce((auth.jwt()->>'is_anonymous')::boolean,true)
 or not exists(select 1 from public.businesses where id=p_business and owner_id=p_actor)
 then raise exception 'Actor denied' using errcode='42501';end if;
 -- Validate exact shape and canonical order before any writes or locks.
 for c in select value from jsonb_array_elements(p_changes) loop
  if jsonb_typeof(c)<>'object' or (select count(*) from jsonb_object_keys(c))<>5
  or not (c ?& array['kind','id','expected_version','schema','snapshot'])
  or jsonb_typeof(c->'kind')<>'string' or (c->>'kind') !~ '^[a-z][a-z0-9_.]{0,63}$'
  or jsonb_typeof(c->'id')<>'string' or (c->>'id') !~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
  or jsonb_typeof(c->'expected_version')<>'number' or (c->>'expected_version') !~ '^(0|[1-9][0-9]{0,17})$'
  or c->'schema'<>'1'::jsonb or jsonb_typeof(c->'snapshot')<>'object'
  then raise exception 'Invalid change contract' using errcode='22023';end if;
 end loop;
 if (select count(*) from (select distinct value->>'kind',value->>'id' from jsonb_array_elements(p_changes)) x)<>jsonb_array_length(p_changes)
 then raise exception 'Duplicate aggregate' using errcode='22023';end if;
 select jsonb_build_object('schema',1,'actor',p_actor,'reason',p_reason,'changes',jsonb_agg(value order by value->>'kind' collate "C",value->>'id' collate "C"))
 into envelope from jsonb_array_elements(p_changes);
 -- One tenant/environment transaction lock FIRST. Hash collisions only serialize.
 -- Multi-business transactions and legacy adapters are not supported.
 perform pg_advisory_xact_lock(hashtextextended(p_business::text||':'||p_environment,73003));
 select * into prior from public.shared_core_commands where business_id=p_business and environment=p_environment and idempotency_key=p_key;
 if found then
  if prior.envelope<>envelope then raise exception 'Idempotency payload conflict' using errcode='22023';end if;
  return prior.result; -- Exact retry wins over expected-version staleness.
 end if;
 for c in select value from jsonb_array_elements(envelope->'changes') loop
  select version into v from public.shared_core_aggregates where business_id=p_business and environment=p_environment and kind=c->>'kind' and id=(c->>'id')::uuid for update;
  v:=coalesce(v,0);
  if v<>(c->>'expected_version')::bigint then raise exception 'Stale aggregate version' using errcode='40001';end if;
  insert into public.shared_core_aggregates values(p_business,p_environment,c->>'kind',(c->>'id')::uuid,v+1,c->'snapshot')
  on conflict(business_id,environment,kind,id) do update set version=excluded.version,snapshot=excluded.snapshot;
  result:=result||jsonb_build_array(jsonb_build_object('kind',c->>'kind','id',c->>'id','version',v+1));
 end loop;
 insert into public.shared_core_commands values(p_business,p_environment,p_key,p_actor,p_reason,envelope,result,transaction_timestamp());
 for c in select value from jsonb_array_elements(envelope->'changes') loop
  ordinal:=ordinal+1;
  insert into public.shared_core_events values(p_business,p_environment,p_key,ordinal,c->>'kind',(c->>'id')::uuid,(c->>'expected_version')::bigint,(c->>'expected_version')::bigint+1,c->'snapshot',1);
 end loop;
 return result;
end $function$

CREATE OR REPLACE FUNCTION public.waitlist_claim(p_only uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare j waitlist_private.outbox; token uuid;
begin
 -- Resend idempotency lasts 24 hours; never retry beyond that safe window.
 update waitlist_private.outbox set status='failed',payload=null,last_error='Retry window expired; review required' where status in ('pending','retry','sending') and created_at<now()-interval '23 hours';
 for j in select o.* from waitlist_private.outbox o join public.waitlist_subscribers s on s.id=o.subscriber_id
 where (o.status in ('pending','retry') or (o.status='sending' and o.next_attempt<now())) and o.next_attempt<=now() and o.attempts<4
 and (p_only is null or o.id=p_only) and ((o.kind='confirmation' and s.status='pending' and s.confirm_expires>now()) or (o.kind='owner' and s.status='confirmed'))
 order by o.created_at for update of o skip locked limit 1 loop
  token:=gen_random_uuid();
  update waitlist_private.outbox set status='sending',attempts=attempts+1,next_attempt=now()+interval '2 minutes',lease=token where id=j.id;
  return jsonb_build_object('id',j.id,'kind',j.kind,'payload',j.payload,'lease',token);
 end loop;
 return null;
end $function$

CREATE OR REPLACE FUNCTION public.waitlist_cleanup()
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
 delete from waitlist_private.rate_limits where expires<now();
 delete from public.waitlist_subscribers where (status='pending' and last_request_at<now()-interval '7 days') or (status in ('withdrawn','suppressed') and coalesce(withdrawn_at,last_request_at)<now()-interval '30 days') or (status='confirmed' and confirmed_at<now()-interval '12 months');
 delete from waitlist_private.outbox where created_at<now()-interval '30 days' and status in ('sent','failed','cancelled');
 delete from waitlist_private.delivery_events where received_at<now()-interval '30 days';
end $function$

CREATE OR REPLACE FUNCTION public.waitlist_delivery(p_event_id text, p_provider_id text, p_event_type text)
 RETURNS boolean
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
 if p_event_type not in ('email.delivered','email.bounced','email.complained','email.failed','email.suppressed') or length(p_event_id)>200 or length(p_provider_id)>100 then return false; end if;
 insert into waitlist_private.delivery_events(event_id,provider_id,event_type) values(p_event_id,p_provider_id,p_event_type) on conflict do nothing;
 if not found then return true; end if;
 update waitlist_private.outbox set delivery_status=p_event_type where provider_id=p_provider_id;
 if p_event_type in ('email.bounced','email.complained','email.suppressed') then
  update public.waitlist_subscribers set status='suppressed',confirm_hash=null,confirm_expires=null where status<>'withdrawn' and id in (select subscriber_id from waitlist_private.outbox where provider_id=p_provider_id and kind='confirmation');
 end if;
 return true;
end $function$

CREATE OR REPLACE FUNCTION public.waitlist_rate(p_bucket text, p_limit integer, p_seconds integer)
 RETURNS boolean
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare n integer;
begin
 if p_limit<1 or p_limit>1000 or p_seconds<1 or p_seconds>86400 or length(p_bucket)<>64 then raise exception 'invalid rate'; end if;
 insert into waitlist_private.rate_limits as r(bucket,hits,expires) values(p_bucket,1,now()+make_interval(secs=>p_seconds))
 on conflict(bucket) do update set hits=r.hits+1 returning hits into n;
 return n<=p_limit;
end $function$

CREATE OR REPLACE FUNCTION public.waitlist_signup(p_name text, p_email text, p_business_type text, p_interests text[], p_consent_version text, p_consent_text text, p_confirm text, p_withdraw text)
 RETURNS uuid
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare s public.waitlist_subscribers; job uuid;
begin
 if p_email is null or p_confirm !~ '^[a-f0-9]{64}$' or p_withdraw !~ '^[a-f0-9]{64}$' or p_confirm is null or p_withdraw is null then raise exception 'invalid request'; end if;
 -- Serializes concurrent requests for the same normalized email before first insert.
 perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(lower(btrim(p_email)),0));
 select * into s from public.waitlist_subscribers where email=lower(btrim(p_email)) for update;
 if found then
  if s.status<>'pending' or s.last_request_at>now()-interval '1 hour' then return null; end if;
  update public.waitlist_subscribers set confirm_hash=encode(extensions.digest(p_confirm,'sha256'),'hex'),confirm_expires=now()+interval '24 hours',withdraw_hash=encode(extensions.digest(p_withdraw,'sha256'),'hex'),last_request_at=now() where id=s.id returning * into s;
  update waitlist_private.outbox set status='cancelled',payload=null where subscriber_id=s.id and status in ('pending','retry');
 else
  insert into public.waitlist_subscribers(email,name,business_type,interests,consent_version,consent_text,confirm_hash,confirm_expires,withdraw_hash)
  values(lower(btrim(p_email)),btrim(p_name),p_business_type,p_interests,p_consent_version,p_consent_text,encode(extensions.digest(p_confirm,'sha256'),'hex'),now()+interval '24 hours',encode(extensions.digest(p_withdraw,'sha256'),'hex')) returning * into s;
 end if;
 insert into waitlist_private.outbox(subscriber_id,kind,payload) values(s.id,'confirmation',jsonb_build_object('to',s.email,'confirm',p_confirm,'withdraw',p_withdraw)) returning id into job;
 return job;
end $function$

CREATE OR REPLACE FUNCTION public.waitlist_transition(p_action text, p_token text)
 RETURNS boolean
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare s public.waitlist_subscribers;
begin
 if p_token is null or p_token !~ '^[a-f0-9]{64}$' then return false; end if;
 if p_action='confirm' then
  update public.waitlist_subscribers set status='confirmed',confirmed_at=now(),confirm_hash=null,confirm_expires=null
  where confirm_hash=encode(extensions.digest(p_token,'sha256'),'hex') and status='pending' and confirm_expires>=now() returning * into s;
  if not found then return false; end if;
  insert into waitlist_private.outbox(subscriber_id,kind,payload) values(s.id,'owner',jsonb_build_object('name',s.name,'email',s.email,'business_type',s.business_type,'interests',s.interests,'confirmed_at',s.confirmed_at));
 elsif p_action='unsubscribe' then
  update public.waitlist_subscribers set status='withdrawn',withdrawn_at=now(),confirm_hash=null,confirm_expires=null,withdraw_hash=null
  where withdraw_hash=encode(extensions.digest(p_token,'sha256'),'hex') and status in ('pending','confirmed') returning * into s;
  if not found then return false; end if;
 else return false;
 end if;
 update waitlist_private.outbox set status='cancelled',payload=null where subscriber_id=s.id and status in ('pending','retry') and (kind='confirmation' or s.status='withdrawn');
 return true;
end $function$

CREATE OR REPLACE FUNCTION quote_private.customer(p_environment text, p_token text, p_response text DEFAULT ''::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare q public.business_quotes;st text;
begin
 if p_token is null or p_token !~ '^[a-f0-9]{64}$' or not exists(select 1 from quote_private.ingress where environment=p_environment and enabled) then return '{}'::jsonb;end if;
 select * into q from public.business_quotes where share_token=p_token and environment=p_environment and status<>'Draft' for update;
 if not found then return '{}'::jsonb;end if;
 st=case when q.status='Sent' and q.expires_on < (now() at time zone (q.sender->>'time_zone'))::date then 'Expired' else q.status end;
 if p_response<>'' then
 if p_response is null or p_response not in ('Accepted','Declined') then raise exception 'Choose accept or decline';end if;
 if st='Sent' then update public.business_quotes set status=p_response,responded_at=now(),version=version+1 where id=q.id;st=p_response;
 elsif st<>p_response then raise exception 'Quote already answered or expired. Reload the page.';end if;
 end if;
 return jsonb_build_object('reference',upper(substr(q.id::text,1,8)),'document',(jsonb_build_object('name',q.document->'name','items',q.document->'items','notes',q.document->'notes','currency',q.document->'currency') || case when q.document ? 'scope' then jsonb_build_object('scope',q.document->'scope') else '{}'::jsonb end),'sender',jsonb_build_object('name',q.sender->'name','email',q.sender->'email','phone',q.sender->'phone','time_zone',q.sender->'time_zone'),'expires_on',q.expires_on,'status',st,'sent_at',q.sent_at);
end$function$

CREATE OR REPLACE FUNCTION quote_private.owner_write(p_business uuid, p_environment text, p_id uuid, p_version integer, p_action text, p_document jsonb, p_expiry date, p_enquiry uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare q public.business_quotes;b public.businesses;c text;z text;s jsonb;scope jsonb;
begin
 select * into b from public.businesses where id=p_business and owner_id=auth.uid() and not coalesce((auth.jwt()->>'is_anonymous')::boolean,true);
 if not found or not exists(select 1 from quote_private.ingress where environment=p_environment and enabled) then raise exception 'Quotes unavailable';end if;
 if p_action not in ('save','send') or p_action is null or p_id is null or p_version is null then raise exception 'Check quote details';end if;
 select * into q from public.business_quotes where id=p_id for update;
 if found then
 if q.business_id<>p_business or q.environment<>p_environment or q.version<>p_version or q.status<>'Draft' then raise exception 'Quote changed or unavailable. Reload before saving.';end if;
 else
 if p_version<>0 or p_action<>'save' then raise exception 'Quote changed or unavailable. Reload before saving.';end if;
 end if;
 if p_action='save' then
 if q.id is not null then scope=q.document->'scope';elsif p_enquiry is not null then select r.scope into scope from public.business_booking_requests r where r.id=p_enquiry and r.business_id=p_business and r.environment=p_environment;end if;
 if scope is not null then p_document=(p_document-'scope')||jsonb_build_object('scope',scope);elsif p_document ? 'scope' then raise exception 'Scope must originate from a booking request.';end if;
 if not quote_private.valid(p_document) or p_expiry is null or p_expiry < (now() at time zone b.time_zone)::date or p_expiry > (now() at time zone b.time_zone)::date+366 then raise exception 'Check quote details and expiry';end if;
 select draft->>'currency' into c from public.business_service_catalogues where business_id=p_business and environment=p_environment;
 if p_document->>'currency'<>coalesce(c,'ZAR') then raise exception 'Business currency changed. Reload before saving.';end if;
 if p_enquiry is not null and not exists(select 1 from public.business_enquiries where id=p_enquiry and business_id=p_business and environment=p_environment) then raise exception 'Enquiry unavailable';end if;
 if q.id is null then insert into public.business_quotes(id,business_id,environment,enquiry_id,document,expires_on) values(p_id,p_business,p_environment,p_enquiry,p_document,p_expiry);
 else update public.business_quotes set document=p_document,expires_on=p_expiry,version=version+1 where id=p_id;end if;
 else
 if q.expires_on < (now() at time zone b.time_zone)::date then raise exception 'Update the expiry before sending.';end if;
 -- Capture explicit public business details only; no account metadata.
 select draft into s from public.business_profiles where business_id=p_business and environment=p_environment;
 s=jsonb_build_object('name',coalesce(nullif(s->>'name',''),b.name),'email',coalesce(s->>'email',''),'phone',coalesce(s->>'phone',''),'time_zone',b.time_zone);
 update public.business_quotes set status='Sent',sender=s,share_token=encode(extensions.gen_random_bytes(32),'hex'),sent_at=now(),version=version+1 where id=p_id;
 end if;
 return jsonb_build_object('id',p_id);
end$function$

CREATE OR REPLACE FUNCTION quote_private.send(p_business uuid, p_environment text, p_id uuid, p_version integer, p_free_confirmed boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare q public.business_quotes;
begin
 if p_environment not in ('preview','live') or p_environment is null or not exists(select 1 from public.businesses where id=p_business and owner_id=auth.uid() and not coalesce((auth.jwt()->>'is_anonymous')::boolean,true)) or not exists(select 1 from quote_private.ingress where environment=p_environment and enabled) then raise exception 'Quotes unavailable';end if;
 select * into q from public.business_quotes where id=p_id and business_id=p_business and environment=p_environment for update;
 if not found or q.version is distinct from p_version or q.status<>'Draft' then raise exception 'Quote changed or unavailable. Reload before saving.';end if;
 if invoice_private.total(q.document)=0 then
 if p_free_confirmed is distinct from true then raise exception 'Confirm this is deliberately a free quote before sending';end if;
 update public.business_quotes set free_confirmed_at=clock_timestamp() where id=q.id;
 end if;
 return quote_private.owner_write(p_business,p_environment,p_id,p_version,'send',q.document,q.expires_on,q.enquiry_id);
end$function$

CREATE OR REPLACE FUNCTION quote_private.valid(d jsonb)
 RETURNS boolean
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO ''
AS $function$
declare s jsonb;k text;t bigint=0;
begin
 if jsonb_typeof(d) is distinct from 'object' or (select count(*) from jsonb_object_keys(d)) not in (6,7) or not d ?& array['name','email','phone','notes','currency','items'] then return false;end if;
 if (select count(*) from jsonb_object_keys(d))=7 and (not d ? 'scope' or not request_private.scope_valid(d->'scope') or d->'scope'->>'currency' is distinct from d->>'currency') then return false;end if;
 foreach k in array array['name','email','phone','notes','currency'] loop
 if jsonb_typeof(d->k) is distinct from 'string' or d->>k ~ '[\u0001-\u0008\u000b\u000c\u000e-\u001f\u007f]' then return false;end if;end loop;
 if char_length(btrim(d->>'name')) not between 2 and 120 or char_length(d->>'email')>254 or char_length(d->>'phone')>40 or char_length(d->>'notes')>4000 or (d->>'email'='' and d->>'phone'='') or (d->>'email'<>'' and d->>'email' !~ '^[^[:space:]@]+@[^[:space:]@]+\.[^[:space:]@]+$') or (d->>'phone'<>'' and (d->>'phone' !~ '^[+0-9 ()-]{5,40}$' or char_length(regexp_replace(d->>'phone','[^0-9]','','g'))<5)) or d->>'currency' not in ('ZAR','USD','GBP','EUR','AUD','CAD','NZD','BWP','NAD','ZMW','KES','NGN','GHS','MUR','SZL','LSL','MZN','UGX','TZS','RWF','JPY','INR','AED','CHF') or jsonb_typeof(d->'items') is distinct from 'array' or jsonb_array_length(d->'items') not between 1 and 20 then return false;end if;
 for s in select value from jsonb_array_elements(d->'items') loop
 if jsonb_typeof(s) is distinct from 'object' or (select count(*) from jsonb_object_keys(s))<>3 or not s ?& array['name','quantity','price'] or jsonb_typeof(s->'name') is distinct from 'string' or char_length(btrim(s->>'name')) not between 2 and 120 or s->>'name' ~ '[[:cntrl:]]' or jsonb_typeof(s->'quantity') is distinct from 'number' or s->>'quantity' !~ '^[0-9]+$' or (s->>'quantity')::bigint not between 1 and 9999 or jsonb_typeof(s->'price') is distinct from 'number' or s->>'price' !~ '^[0-9]+$' or (s->>'price')::bigint not between 0 and 999999999 then return false;end if;
 if d->>'currency' in ('JPY','UGX','RWF') and (s->>'price')::bigint%100<>0 then return false;end if;
 t=t+(s->>'quantity')::bigint*(s->>'price')::bigint;
 end loop;return t<=999999999;
exception when others then return false;
end$function$

CREATE OR REPLACE FUNCTION request_private.action(p_business uuid, p_environment text, p_id uuid, p_version integer, p_action text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare r public.business_booking_requests;e public.business_enquiries;b public.businesses;q public.business_quotes;d jsonb;bid uuid;
begin
 select * into b from public.businesses where id=p_business and owner_id=auth.uid() and not coalesce((auth.jwt()->>'is_anonymous')::boolean,true);
 if not found or not exists(select 1 from request_private.ingress where environment=p_environment and enabled) then raise exception 'Requests unavailable.';end if;
 -- Same serialization as ordinary quote conversion: no second booking even across both entry points.
 perform pg_advisory_xact_lock(hashtextextended(p_business::text,32));
 select * into r from public.business_booking_requests where id=p_id and business_id=p_business and environment=p_environment for update;
 if not found or p_action is null or p_action not in ('quote','accept','decline','convert') then raise exception 'Request unavailable.';end if;
 if r.booking_id is not null and p_action='convert' then return jsonb_build_object('booking_id',r.booking_id);end if;
 if r.version is distinct from p_version then raise exception 'Request changed. Reload before updating.';end if;
 select * into e from public.business_enquiries where id=r.id;
 if p_action='quote' then
 if r.status<>'Pending' then raise exception 'Only pending requests can be quoted.';end if;
 if r.quote_id is not null then return jsonb_build_object('quote_id',r.quote_id);end if;
 if not exists(select 1 from quote_private.ingress where environment=p_environment and enabled) then raise exception 'Quotes unavailable.';end if;
 -- Reuse an existing quote from this enquiry if it was created through Enquiries.
 select * into q from public.business_quotes where enquiry_id=r.id and business_id=p_business and environment=p_environment order by created_at,id limit 1 for update;
 if not found then
 if r.currency is distinct from coalesce((select draft->>'currency' from public.business_service_catalogues where business_id=p_business and environment=p_environment),'ZAR') then raise exception 'Catalogue currency changed. Review this request before quoting.';end if;
 d=jsonb_build_object('name',e.customer_name,'email',e.email,'phone',e.phone,'notes',e.requirements,'currency',r.currency,'items',jsonb_build_array(jsonb_build_object('name',r.service->>'name','quantity',1,'price',coalesce((r.service->>'amount')::integer,0))));
 if r.scope is not null then d=jsonb_set(d,'{items}',r.scope->'items')||jsonb_build_object('scope',r.scope);end if;
 bid=gen_random_uuid();
 perform quote_private.owner_write(p_business,p_environment,bid,0,'save',d,(now() at time zone b.time_zone)::date+14,r.id);
 else if r.scope is not null and q.document->'scope' is distinct from r.scope then raise exception 'Existing quote does not preserve requested rooms and extras. Review separately.';end if;bid=q.id;end if;
 update public.business_booking_requests set quote_id=bid,version=version+1,updated_at=now() where id=r.id;
 return jsonb_build_object('quote_id',bid);
 elsif p_action='decline' then
 if r.status<>'Pending' then raise exception 'Only pending requests can be declined.';end if;
 update public.business_booking_requests set status='Declined',version=version+1,updated_at=now() where id=r.id;
 elsif p_action='accept' then
 if r.status<>'Pending' then raise exception 'Only pending requests can be accepted.';end if;
 if r.quote_id is not null then
 select * into q from public.business_quotes where id=r.quote_id and business_id=p_business and environment=p_environment for update;
 if q.status is distinct from 'Accepted' then raise exception 'The customer must accept the quote first.';end if;
 elsif r.service->>'mode' is distinct from 'fixed' then raise exception 'Create a quote and obtain customer acceptance first.';end if;
 update public.business_booking_requests set status='Accepted',version=version+1,updated_at=now() where id=r.id;
 else
 if r.status<>'Accepted' or not exists(select 1 from booking_private.ingress where environment=p_environment and enabled) then raise exception 'Accept this request before creating a booking.';end if;
 if r.preferred_at<=now() then raise exception 'Preferred time has passed. Review with the customer before booking.';end if;
 if r.quote_id is not null then
 select * into q from public.business_quotes where id=r.quote_id and business_id=p_business and environment=p_environment and status='Accepted' for update;
 if not found then raise exception 'Accepted quote unavailable.';end if;
 select id into bid from public.business_bookings where quote_id=q.id;
 d=q.document;
 else
 d=jsonb_build_object('name',e.customer_name,'email',e.email,'phone',e.phone,'notes',e.requirements,'currency',r.currency,'items',jsonb_build_array(jsonb_build_object('name',r.service->>'name','quantity',1,'price',(r.service->>'amount')::integer)));
 end if;
 if r.scope is not null and r.quote_id is null then d=jsonb_set(d,'{items}',r.scope->'items')||jsonb_build_object('scope',r.scope);end if;
 if not quote_private.valid(d) then raise exception 'Invalid booking agreement.';end if;
 if bid is null then
 bid=gen_random_uuid();
 insert into public.business_bookings(id,business_id,environment,quote_id,document,address,starts_at,time_zone,duration_minutes,customer_id) values(bid,p_business,p_environment,r.quote_id,d,r.address,r.preferred_at,r.time_zone,coalesce((r.scope->>'minutes')::integer,(r.service->>'duration')::integer),coalesce(q.customer_id,e.customer_id));
 end if;
 update public.business_booking_requests set status='Booked',booking_id=bid,version=version+1,updated_at=now() where id=r.id;
 return jsonb_build_object('booking_id',bid);
 end if;
 return '{}'::jsonb;
end$function$

CREATE OR REPLACE FUNCTION request_private.calculate(s jsonb, c text, a jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO ''
AS $function$
declare o jsonb;v jsonb;q bigint;charge bigint;t bigint=coalesce((s->>'amount')::bigint,0);m bigint=(s->>'duration')::bigint; rows jsonb='[]';canonical jsonb='[]';items jsonb; ids text[]='{}';
begin
 if not request_private.options_valid(coalesce(s->'options','[]')) or jsonb_typeof(a) is distinct from 'array' or jsonb_array_length(a)>19 then raise exception 'Check room and extra selections.';end if;
 for v in select value from jsonb_array_elements(a) loop
 if jsonb_typeof(v) is distinct from 'object' or (select count(*) from jsonb_object_keys(v))<>2 or not v ?& array['id','quantity'] or jsonb_typeof(v->'id') is distinct from 'string' or v->>'id'=any(ids) or jsonb_typeof(v->'quantity') is distinct from 'number' or v->>'quantity' !~ '^[0-9]+$' or not exists(select 1 from jsonb_array_elements(coalesce(s->'options','[]')) x where x->>'id'=v->>'id') then raise exception 'Check room and extra selections.';end if;
 ids=array_append(ids,v->>'id');
 end loop;
 items=jsonb_build_array(jsonb_build_object('name',s->>'name','quantity',1,'price',coalesce((s->>'amount')::bigint,0)));
 for o in select value from jsonb_array_elements(coalesce(s->'options','[]')) loop
 select (x->>'quantity')::bigint into q from jsonb_array_elements(a) x where x->>'id'=o->>'id';
 if q is null or q<(o->>'minimum')::bigint or q>(o->>'maximum')::bigint then raise exception 'Check room and extra quantities.';end if;
 canonical=canonical||jsonb_build_array(jsonb_build_object('id',o->>'id','quantity',q));
 charge=greatest(0,q-(o->>'included')::bigint);
 if c in ('JPY','UGX','RWF') and (o->>'price')::bigint%100<>0 then raise exception 'Use whole currency amounts.';end if;
 t=t+charge*(o->>'price')::bigint;m=m+charge*(o->>'minutes')::bigint;
 rows=rows||jsonb_build_array(o||jsonb_build_object('quantity',q,'chargeable',charge));
 if charge>0 then items=items||jsonb_build_array(jsonb_build_object('name',o->>'name','quantity',charge,'price',(o->>'price')::bigint));end if;
 end loop;
 if t>999999999 or m not between 1 and 10080 then raise exception 'Selected scope exceeds supported price or duration.';end if;
 return jsonb_build_object('schema',1,'service',s,'currency',c,'selections',canonical,'rows',rows,'items',items,'total',case when s->>'mode'='quote' then null else t end,'minutes',m);
end$function$

CREATE OR REPLACE FUNCTION request_private.options_valid(a jsonb)
 RETURNS boolean
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO ''
AS $function$
declare o jsonb; ids text[]='{}'; k text;
begin
 if jsonb_typeof(a) is distinct from 'array' or jsonb_array_length(a)>19 then return false;end if;
 for o in select value from jsonb_array_elements(a) loop
 if jsonb_typeof(o) is distinct from 'object' or (select count(*) from jsonb_object_keys(o))<>8 or not o ?& array['id','name','kind','minimum','maximum','included','price','minutes'] then return false;end if;
 if jsonb_typeof(o->'id') is distinct from 'string' or o->>'id' !~ '^[a-f0-9]{32}$' or o->>'id'=any(ids) or jsonb_typeof(o->'name') is distinct from 'string' or char_length(btrim(o->>'name')) not between 2 and 100 or o->>'name' ~ '[[:cntrl:]]' or jsonb_typeof(o->'kind') is distinct from 'string' or o->>'kind' not in ('bedrooms','bathrooms','room','extra','toggle') then return false;end if;
 ids=array_append(ids,o->>'id');
 foreach k in array array['minimum','maximum','included','price','minutes'] loop
 if jsonb_typeof(o->k) is distinct from 'number' or o->>k !~ '^[0-9]+$' then return false;end if;
 end loop;
 if (o->>'minimum')::bigint>(o->>'maximum')::bigint or (o->>'maximum')::bigint>9999 or (o->>'included')::bigint>(o->>'maximum')::bigint or (o->>'price')::bigint>999999999 or (o->>'minutes')::bigint>10080 or (o->>'kind'='toggle' and (o->>'maximum')::int<>1) then return false;end if;
 end loop;
 if (select count(*) from jsonb_array_elements(a) as entries(option) where entries.option->>'kind'='bedrooms')>1 or (select count(*) from jsonb_array_elements(a) as entries(option) where entries.option->>'kind'='bathrooms')>1 then return false;end if;
 return true;
exception when others then return false;end$function$

CREATE OR REPLACE FUNCTION request_private.submit(p_environment text, p_slug text, p_service text, p_name text, p_email text, p_phone text, p_requirements text, p_request uuid, p_address text, p_local timestamp without time zone, p_zone text, p_currency text, p_service_snapshot jsonb, p_selections jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare page public.business_public_pages;s jsonb;e public.business_enquiries;r public.business_booking_requests;t timestamptz;scope jsonb;
begin
 if not exists(select 1 from request_private.ingress where environment=p_environment and enabled) then raise exception 'Booking requests unavailable.';end if;
 select * into page from public.business_public_pages where environment=p_environment and slug=p_slug for share;
 if not found then raise exception 'Page unavailable.';end if;
 select value into s from jsonb_array_elements(page.services->'items') where value->>'id'=p_service and value->>'visible'='true' and value->>'archived'='false';
 if s is null or s is distinct from p_service_snapshot or page.time_zone is distinct from p_zone or page.services->>'currency' is distinct from p_currency then raise exception 'Service, price or time zone changed. Reload before submitting.';end if;
 if p_address is null or char_length(btrim(p_address)) not between 5 and 1000 or p_address ~ '[\u0001-\u0008\u000b\u000c\u000e-\u001f\u007f]' or p_local is null or p_local>=timestamp '2100-01-01' or p_requirements is null or char_length(p_requirements)>2000 then raise exception 'Check address, schedule and requirements.';end if;
 scope=case when jsonb_array_length(coalesce(s->'options','[]'))>0 then request_private.calculate(s,p_currency,p_selections) else null end;
 if scope is null and p_selections<>'[]'::jsonb then raise exception 'Service has no room or extra options.';end if;
 t=booking_private.instant(p_local,p_zone);
 -- Shared intake provides contact validation, publication lock, database spam caps and request idempotency.
 perform enquiry_private.submit(p_environment,p_slug,p_service,p_name,p_email,p_phone,p_requirements,p_request);
 select * into e from public.business_enquiries where request_id=p_request;
 select * into r from public.business_booking_requests where id=e.id for update;
 if found then
 if r.address=btrim(p_address) and r.preferred_at=t and r.time_zone=p_zone and r.currency=p_currency and r.service=s and r.scope is not distinct from scope then return '{}'::jsonb;end if;
 raise exception 'Request already used.';
 end if;
 if t<=now() then raise exception 'Choose a preferred date and time in the future.';end if;
 insert into public.business_booking_requests(id,business_id,environment,service,currency,time_zone,address,preferred_at,scope) values(e.id,e.business_id,p_environment,s,p_currency,p_zone,btrim(p_address),t,scope);
 return '{}'::jsonb;
end$function$

CREATE OR REPLACE FUNCTION staff_private.assign(p_business uuid, p_environment text, p_booking uuid, p_version integer, p_staff jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare b public.business_bookings;ids uuid[];
begin
 perform staff_private.owner(p_business,p_environment);
 perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(p_business::text,91));
 select * into b from public.business_bookings where id=p_booking and business_id=p_business and environment=p_environment for update;
 if not found or p_version is distinct from b.assignment_version then raise exception 'Assignments changed or unavailable. Reload before saving.';end if;
 if jsonb_typeof(p_staff) is distinct from 'array' or jsonb_array_length(p_staff)>100 then raise exception 'Choose up to 100 staff members.';end if;
 if exists(select 1 from jsonb_array_elements(p_staff) x where jsonb_typeof(x)<>'string' or x#>>'{}' !~ '^[0-9a-f]{8}(-[0-9a-f]{4}){3}-[0-9a-f]{12}$') then raise exception 'Choose valid staff members.';end if;
 select coalesce(array_agg(distinct x::uuid),'{}'::uuid[]) into ids from jsonb_array_elements_text(p_staff) x;
 if exists(select 1 from unnest(ids) i where not exists(select 1 from public.business_staff s where s.id=i and s.business_id=p_business and s.environment=p_environment and (s.active or exists(select 1 from public.business_booking_staff a where a.booking_id=p_booking and a.staff_id=s.id)))) then raise exception 'Choose active staff from this business. Existing inactive assignments may be retained.';end if;
 delete from public.business_booking_staff where booking_id=p_booking and not(staff_id=any(ids));
 insert into public.business_booking_staff(booking_id,staff_id,business_id,environment) select p_booking,i,p_business,p_environment from unnest(ids)i on conflict do nothing;
 update public.business_bookings set assignment_version=assignment_version+1 where id=p_booking;
 return jsonb_build_object('id',p_booking);
end$function$

CREATE OR REPLACE FUNCTION staff_private.write(p_business uuid, p_environment text, p_id uuid, p_version integer, p_name text, p_email text, p_phone text, p_active boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare s public.business_staff;
begin
 perform staff_private.owner(p_business,p_environment);
 perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(p_business::text,91));
 if p_id is null or p_version is null or p_version<0 or p_name is null or char_length(btrim(p_name)) not between 2 and 120 or p_name ~ '[\u0001-\u001f\u007f]' or p_email is null or char_length(p_email)>254 or (p_email<>'' and p_email !~ '^[^[:space:]@]+@[^[:space:]@]+\.[^[:space:]@]+$') or p_phone is null or (p_phone<>'' and (p_phone !~ '^[+0-9 ()-]{5,40}$' or char_length(regexp_replace(p_phone,'[^0-9]','','g'))<5)) or p_active is null then raise exception 'Check staff details.';end if;
 select * into s from public.business_staff where id=p_id for update;
 if (s.id is not null and (s.business_id<>p_business or s.environment<>p_environment or s.version<>p_version)) or (s.id is null and p_version<>0) then raise exception 'Staff changed or unavailable. Reload before saving.';end if;
 if s.id is null then insert into public.business_staff(id,business_id,environment,name,email,phone,active) values(p_id,p_business,p_environment,btrim(p_name),btrim(p_email),btrim(p_phone),p_active);
 else update public.business_staff set name=btrim(p_name),email=btrim(p_email),phone=btrim(p_phone),active=p_active,version=version+1,updated_at=now() where id=p_id;end if;
 return jsonb_build_object('id',p_id);
end$function$
